-- PostgreSQL 15+ migration template (MySQL variant at the end). Relational engines
-- only: MongoDB shape changes are in-place backfills (see the MongoDB gotcha in SKILL.md).
-- Syntax is standard on PostgreSQL 18 and MySQL 8.4 (https://www.postgresql.org/docs/current/sql-createtable.html,
-- https://dev.mysql.com/doc/refman/8.4/en/datetime.html, checked 2026-11-07); run it on the target engine.
-- Migration: YYYYMMDDHHMMSS_descriptive_name.sql
-- Description: [What this migration does]
-- Author: [Your Name]
-- Date: YYYY-MM-DD
-- Live table? [Yes/No]. If yes, follow references/migrations.md first:
-- CREATE INDEX CONCURRENTLY cannot run in this transaction and needs its own
-- non-transactional migration, and NOT VALID / VALIDATE / SET NOT NULL phases
-- each go in their own migration so no lock is held across a scan.

-- ============================================================================
-- UP MIGRATION
-- ============================================================================

BEGIN;
SET LOCAL lock_timeout = '5s';  -- fail fast instead of queueing every reader behind this DDL

-- Step 1: Create table
CREATE TABLE IF NOT EXISTS table_name (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reference_id BIGINT NOT NULL,
  column_name VARCHAR(255) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),  -- instant: stored as UTC
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()   -- PostgreSQL has no ON UPDATE; set it in app code or a trigger
);

-- Step 2: Foreign keys. Pick ON DELETE deliberately (RESTRICT, CASCADE or SET NULL).
ALTER TABLE table_name
  ADD CONSTRAINT fk_table_reference
  FOREIGN KEY (reference_id) REFERENCES other_table(id)
  ON DELETE RESTRICT;

-- Step 3: Indexes, one per named query or FK path.
-- This one serves parent deletes on other_table and lookups by reference_id.
CREATE INDEX idx_table_reference ON table_name (reference_id);

COMMIT;

-- ============================================================================
-- DOWN MIGRATION (destroys rows written since UP; state it in the PR)
-- ============================================================================

-- BEGIN;
-- DROP TABLE IF EXISTS table_name;  -- also drops its indexes and constraints
-- COMMIT;

-- ============================================================================
-- VALIDATION (PostgreSQL)
-- ============================================================================

-- SELECT to_regclass('table_name');                        -- NULL if missing
-- SELECT indexname FROM pg_indexes WHERE tablename = 'table_name';
-- SELECT indexrelid::regclass FROM pg_index WHERE NOT indisvalid;  -- leftovers of a failed CONCURRENTLY build

-- ============================================================================
-- MySQL 8 variant (InnoDB). DDL commits implicitly, so BEGIN/COMMIT gives no
-- atomicity: keep one DDL statement per migration or make each idempotent.
-- ============================================================================
-- DATETIME has no zone and CURRENT_TIMESTAMP uses the session time_zone, so every
-- app connection must run SET time_zone = '+00:00' for these defaults to be UTC.
-- CREATE TABLE table_name (
--   id BIGINT AUTO_INCREMENT PRIMARY KEY,
--   reference_id BIGINT NOT NULL,
--   column_name VARCHAR(255) NOT NULL,
--   created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
--   updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
--   CONSTRAINT fk_table_reference FOREIGN KEY (reference_id) REFERENCES other_table(id) ON DELETE RESTRICT
-- ) ENGINE=InnoDB;  -- InnoDB creates the reference_id index for the FK itself
-- Validate: SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES
--   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'table_name';
-- Validate indexes: SHOW INDEX FROM table_name;

-- Estimated time: [X seconds on Y rows]
-- Requires downtime: [Yes/No]
-- Rollback tested: [Yes/No]
